
=== Drop old alias table
DROP TABLE IF EXISTS alias_articoli;

=== Read alias
CREATE EXTERNAL TABLE alias_articoli (
  `CODALIAS` STRING,
  `PROGR`    STRING,
  `DESCRIZ`  STRING,
  `ARTICOLO` STRING,
  `NOTE1`    STRING,
  `NOTE2`    STRING,
  `DATCREAZ` STRING,
  `DATAGG`   STRING,
  `COLLI` STRING,
  `QTA`   STRING,
  `UMIS`  STRING
)
USING CSV
LOCATION 'file://${ALIAS_CSV_PATH}'
OPTIONS (
  'header'='true', 
  'delimiter' = ';',
  'encoding' = 'ISO-8859-1'
)
;


