=== Definisci vista foglio articoli del drive magazzino senza formule
CREATE OR REPLACE TEMP VIEW foglio_articoli_no_formule AS (
  SELECT
    art_1._arcod as codice_articolo,
    art_1._arann as nd_column_flag,
    art_1._ardes || coalesce( _aragg, '') as descrizione_articolo,
    date_format(to_date(art_1._ardtc, 'ddMMyyyy'), 'yyyy-MM-dd') as data_config_articolo,
    art_alias.codalias as descrizione_breve_articolo,
    art_alias.descriz as descrizione_breve_2_articolo,
    art_1._ARUM1 as unit_misura_articolo,
    art_1._ARUM2 as unit_misura_2_articolo,
    cast(
      replace(replace(art_1._ARKOEPTA, '.', ''), ',', '.') 
      as DECIMAL(12, 6)
    )
     as coeff_um1_to_um2_articolo,
    art_1._ARALT as cod_barre_articolo,
    art_1.GRPMERCE as codice_categoria,
    'DA TROVARE' as descrizione_categoria,
    art_1.NATURA as codice_tipologia,
    'DA TROVARE' as descrizione_tipologia,
    art_1._ARFOR_1 as codice_fornitore,
    (
      case 
        when art_1._ARFOR_1 = '60100001' THEN 'Prova 1'
        when art_1._ARFOR_1 = '50100001' THEN 'Camilla'
        else f._PCRIC
      end
    )
     as descrizione_fornitore,
    cast(
      replace(replace(art_1._ARCUP, '.', ''), ',', '.') 
      as DECIMAL(12, 6)
    )
     as costo_articolo,
    art_1._ARIVA as iva_articolo_str,
    if ( 
      art_1._ARIVA in ('F02,2', 'S74', 'Q01'),
      null,
      cast(
        replace(replace(art_1._ARIVA, '.', ''), ',', '.') 
        as DECIMAL(12, 6)
      )
    )
     as iva_articolo,
    cast(
      replace(replace(art_5.PREZZO, '.', ''), ',', '.') 
      as DECIMAL(12, 6)
    )
     as prezzo_articolo,
    art_1._ARLIS as ricarico_rif_articolo
  FROM 
    articoli_1 art_1
    LEFT JOIN alias_articoli art_alias 
      ON art_1._arcod = art_alias.articolo
    LEFT JOIN fornitori f 
      ON f._pccod = art_1._arfor_1
    LEFT JOIN articoli_5 art_5 
      ON art_5.COD = art_1._arcod
)
;

=== Definisci vista foglio articoli del drive magazzino con anche le formule
CREATE OR REPLACE TEMP VIEW foglio_articoli AS (
  SELECT
    *,
    ( 
      prezzo_articolo / coeff_um1_to_um2_articolo 
    ) 
     as prezzo_al_kg_o_lt,
    (
      (
        prezzo_articolo
        /
        (
          costo_articolo * (1+ (iva_articolo/100) )
        )
      )
      -1
    )
     as ricarico
  FROM 
    foglio_articoli_no_formule
)
;
